// FIRST: run the Postiz channel-check workflow and copy one allowed integrationId.
// SECOND: replace these placeholders with your harmless test post.
const integrationId = 'REPLACE_WITH_POSTIZ_INTEGRATION_ID';
const content = 'Test post AURELIUS. This is a harmless preview, not a real advertisement.';
const region = 'Kraków, Poland';
const mediaUrl = ''; // Optional public HTTPS image URL
if (integrationId.startsWith('REPLACE_')) throw new Error('Set integrationId from connected Postiz channels first');
if (content.length < 10) throw new Error('Provide a meaningful draft');
const requestId = 'aurelius-' + Date.now().toString(36);
return [{json:{action:'draft',integrationId,content,region,requestId,...(mediaUrl?{mediaUrl}:{})}}];

